class Solution {
    public int[] closestPrimes(int left,int right){
        boolean[] prime=new boolean[right+1];
        Arrays.fill(prime,true);
        if(right>=0)prime[0]=false;
        if(right>=1)prime[1]=false;
        for(int value=2;value*value<=right;value++)if(prime[value])for(int multiple=value*value;multiple<=right;multiple+=value)prime[multiple]=false;
        int previous=-1,best=Integer.MAX_VALUE;
        int[] answer={
            -1,-1
        };
        for(int value=Math.max(2,left);value<=right;value++)if(prime[value]){
            if(previous>=0&&value-previous<best){
                best=value-previous;
                answer[0]=previous;
                answer[1]=value;
            }
            previous=value;
        }
        return answer;
    }
}

